        value = self._parse_unary()
        while True:
            kind, operator = self._peek()
            if kind != "op" or operator not in {"*", "/"}:
                return value
            self._take()
            right = self._parse_unary()
            if operator == "*":
                value = _number(value) * _number(right)
            else:
                value = _number(value) / _number(right)

