        if self._accept("+"):
            return _number(self._parse_unary())
        if self._accept("-"):
            return -_number(self._parse_unary())
        return self._parse_primary()

    def _parse_primary(self) -> Any:
        kind, value = self._peek()

        if value == "(":
            self._take()
            result = self._parse_or()
            if not self._accept(")"):
                raise ValueError("missing closing parenthesis")
            return result

        if kind == "string":
            self._take()
            return value[1:-1].replace("''", "'")

        if kind == "number":
            self._take()
            return Decimal(value)

        if kind == "ident":
            self._take()
            name = value.upper()
            if self._accept("("):
                argument = self._parse_or()
                if name == "NVL":
                    if not self._accept(","):
                        raise ValueError("NVL requires two arguments")
                    default = self._parse_or()
                    if not self._accept(")"):
                        raise ValueError("missing function parenthesis")
                    return default if _is_empty(argument) else argument
                if name == "LEN":
                    if not self._accept(")"):
                        raise ValueError("missing function parenthesis")
                    return len("" if _is_empty(argument) else str(argument))
                if name == "UPPER":
                    if not self._accept(")"):
                        raise ValueError("missing function parenthesis")
                    return ("" if _is_empty(argument) else str(argument)).upper()
                raise ValueError("unsupported VRL function")
            return self._record.get(value, "")

        raise ValueError("unexpected VRL value")

    @staticmethod
    def _compare(left: Any, operator: str, right: Any) -> bool:
        numeric = isinstance(left, (int, float, Decimal)) or isinstance(
            right, (int, float, Decimal)
        )

        if numeric:
            lhs, rhs = _number(left), _number(right)
        else:
            lhs, rhs = (
                "" if _is_empty(left) else str(left),
                "" if _is_empty(right) else str(right),
            )

        if operator == "=":
            return lhs == rhs
        if operator == "<>":
            return lhs != rhs
        if operator == "<":
            return lhs < rhs
        if operator == "<=":
            return lhs <= rhs
        if operator == ">":
            return lhs > rhs
        return lhs >= rhs


