    ("P", "Q", "qualify", "NVL(AMT,0) > 0", (("set", "STAGE_PCT", "25"), ("audit", "OPP_QUAL"))),
    ("Q", "N", "advance", None, (("set", "STAGE_PCT", "60"),)),
