        "N",
        "W",
        "close_won",
        "CLOSE_DT <> '00000000'",
        (("set", "STAGE_PCT", "100"), ("audit", "OPP_WON"), ("notify", "won_deal")),
    ),
    (
        "P",
        "L",
        "close_lost",
        "LOST_RSN <> ''",
        (("set", "STAGE_PCT", "0"), ("audit", "OPP_LOST")),
    ),
    (
        "Q",
        "L",
        "close_lost",
        "LOST_RSN <> ''",
        (("set", "STAGE_PCT", "0"), ("audit", "OPP_LOST")),
    ),
    (
        "N",
        "L",
        "close_lost",
        "LOST_RSN <> ''",
        (("set", "STAGE_PCT", "0"), ("audit", "OPP_LOST")),
    ),
)


def fire(state: str, event: str, record: dict) -> dict:
    """Fire the first matching opportunity workflow transition."""
    updated = dict(record)

    for source, target, transition_event, guard, actions in _TRANSITIONS:
        if source != state or transition_event != event:
            continue
        if guard is not None and not _guard(guard, updated):
            continue

        audits: list[str] = []
        notifies: list[str] = []

        for action in actions:
            kind = action[0]
            if kind == "set":
                field, value = action[1], action[2]
                updated[field] = (
                    _Parser(value[1:], updated).evaluate()
                    if value.startswith("=")
                    else value
                )
            elif kind == "audit":
                audits.append(action[1])
            elif kind == "notify":
                notifies.append(action[1])

        return {
            "state": target,
            "record": updated,
            "audits": audits,
            "notifies": notifies,
            "matched": True,
        }

    return {
        "state": state,
        "record": updated,
        "audits": ["WF_NOMATCH"],
        "notifies": [],
        "matched": False,
    }
